package com.jjkcraft.technique;

import com.jjkcraft.technique.behavior.*;

/** Explicit copies keep active casts immutable and registry codecs untouched. Generated by tools/generate_tuned_behaviors.py. */
public final class TunedBehaviors {
    private TunedBehaviors() { }
    public static boolean output(TechniqueBehavior b) {
        return !(b instanceof MangaAbilityBehavior m && java.util.Set.of("body_transfer","swap").contains(m.ability()));
    }
    public static boolean area(TechniqueBehavior b) {
        if(b instanceof MangaAbilityBehavior m&&m.ability().startsWith("original/")&&(m.ability().endsWith("/step")||m.ability().endsWith("/guard")&&!m.ability().startsWith("original/ink/")&&!m.ability().startsWith("original/sand/")))return false;
        if(b instanceof MangaAbilityBehavior m && java.util.Set.of("body_transfer","curse_manipulation","swap","mass","armor","flowing_blood","flight").contains(m.ability()))return false;
        return b instanceof ArcSlashBehavior || b instanceof BarrageBehavior || b instanceof BarrierBehavior || b instanceof CursedSpeechBehavior || b instanceof FieldBehavior || b instanceof InfinityBehavior || b instanceof LineCutBehavior || b instanceof MangaAbilityBehavior || b instanceof ProjectileBehavior || b instanceof ProjectionSorceryBehavior || b instanceof ShockwaveBehavior || b instanceof SingularityBehavior;
    }
    public static boolean duration(TechniqueDefinition definition) {
        TechniqueBehavior b=definition.behavior();
        if(b instanceof MangaAbilityBehavior m&&m.ability().startsWith("original/")&&m.ability().endsWith("/step"))return false;
        if(b instanceof MangaAbilityBehavior m && java.util.Set.of("body_transfer","curse_manipulation","uzumaki","swap","repel").contains(m.ability()))return false;
        return definition.cast().maxDuration()>0 || b instanceof BindBehavior || b instanceof CursedSpeechBehavior || b instanceof FieldBehavior || b instanceof IdleTransfigurationBehavior || b instanceof MangaAbilityBehavior || b instanceof MendOtherBehavior || b instanceof ProjectileBehavior || b instanceof ProjectionSorceryBehavior || b instanceof SingularityBehavior || b instanceof StrawDollBehavior || b instanceof SummonBehavior || b instanceof FusionBehavior || b instanceof ThornsAuraBehavior;
    }
    public static boolean reach(TechniqueDefinition definition) {
        TechniqueBehavior b=definition.behavior();return definition.cast().range()>0 || b instanceof DashBehavior || b instanceof ProjectileBehavior || b instanceof ProjectionSorceryBehavior || b instanceof SingularityBehavior;
    }
    private static int ticks(int base,double factor){return Math.max(base==0?0:1,Math.min(36000,(int)Math.round(base*factor)));}
    public static TechniqueBehavior apply(TechniqueBehavior behavior,TechniqueTuning t) {
        double p=t.output()/100.0,r=t.reach()/100.0,a=t.area()/100.0,d=t.duration()/100.0;
        return switch(behavior) {
            case ArcSlashBehavior b -> new ArcSlashBehavior(b.damage(),Math.min(360, b.arc()*a),b.ceScaling(),b.knockback()*Math.sqrt(p)*t.details().force()/100.0);
            case BarrageBehavior b -> new BarrageBehavior(Math.min(64, b.radius()*a),Math.min(64, b.strikeRadius()*a),b.damage(),t.details().expression().pulse()==0?b.interval():t.details().expression().pulse());
            case BarrierBehavior b -> new BarrierBehavior(Math.min(0.95,b.block()*Math.sqrt(p)*t.details().force()/100.0),Math.min(360, b.arc()*a),b.cePerDamage());
            case BindBehavior b -> new BindBehavior(ticks(b.duration(),d),b.damage());
            case CursedSpeechBehavior b -> new CursedSpeechBehavior(b.command(),Math.min(64, b.radius()*a),ticks(b.duration(),d),b.damage(),b.strain());
            case DashBehavior b -> new DashBehavior(Math.min(64,b.distance()*r),Math.min(20,ticks(b.invulnerableTicks(),p)));
            case FieldBehavior b -> new FieldBehavior(b.strength()*Math.sqrt(p)*t.details().force()/100.0,Math.min(64, b.radius()*a),ticks(b.duration(),d),b.damagePerSecond(),b.burstDamage(),Math.min(64, b.burstRadius()*a));
            case HealBehavior b -> new HealBehavior(b.healthPerSecond(),b.cePerHealth()*Math.sqrt(p));
            case IdleTransfigurationBehavior b -> new IdleTransfigurationBehavior(ticks(b.selfTicks(),d),ticks(b.otherTicks(),d));
            case InfinityBehavior b -> new InfinityBehavior(Math.min(64, b.radius()*a),Math.pow(b.slow(),p),b.minSpeed(),t.mode());
            case LineCutBehavior b -> new LineCutBehavior(b.damage(),Math.min(64, b.width()*a),t.details().penetration()<0?b.pierce():t.details().penetration()/100.0);
            case MangaAbilityBehavior b -> new MangaAbilityBehavior(b.ability(),b.damage(),ticks(b.duration(),d),Math.min(64, b.radius()*a));
            case MendOtherBehavior b -> new MendOtherBehavior(b.amount(),ticks(b.regenTicks(),d),b.selfFraction());
            case ProjectileBehavior b -> new ProjectileBehavior(b.damage(),Math.min(8,b.speed()*t.details().speed()/100.0),t.details().homing()==0?b.homing():t.details().homing()==2,Math.min(1,b.homingStrength()*t.details().expression().steering()/100.0),Math.min(64, b.blastRadius()*a),t.details().penetration()<0?b.pierce():t.details().penetration()>=50,(float)Math.min(8,b.size()*a*t.details().expression().size()/100.0),ticks(b.lifetime(),d*r),t.details().expression().gravity()<0?b.gravity():t.details().expression().gravity()/1000.0,t.details().shots()==0?b.count():t.details().shots(),t.details().spread()<0?b.spread():t.details().spread(),Math.min(20,ticks(b.burnSeconds(),d)));
            case ProjectionSorceryBehavior b -> new ProjectionSorceryBehavior(Math.min(64, b.radius()*a),ticks(b.skipTicks(),d),Math.min(64,b.blink()*r));
            case ShockwaveBehavior b -> new ShockwaveBehavior(Math.min(64, b.radius()*a),b.damage(),b.launch()*Math.sqrt(p)*t.details().force()/100.0);
            case SingularityBehavior b -> new SingularityBehavior(Math.min(64,b.distance()*r),Math.min(64, b.radius()*a),ticks(b.pullTicks(),d),b.strength()*Math.sqrt(p)*t.details().force()/100.0,b.damage(),Math.min(64, b.blastRadius()*a));
            case StrawDollBehavior b -> new StrawDollBehavior(b.damage(),b.nails(),ticks(b.duration(),d));
            case StrikeBehavior b -> new StrikeBehavior(b.damage(),b.knockback()*Math.sqrt(p)*t.details().force()/100.0,b.blackFlash());
            case FusionBehavior b -> new FusionBehavior(b.components(),b.result(),ticks(b.lifetime(),d));
            case SummonBehavior b -> new SummonBehavior(b.entity(),t.details().expression().summons()==0?b.count():t.details().expression().summons(),ticks(b.lifetime(),d));
            case ThornsAuraBehavior b -> new ThornsAuraBehavior(b.damage(),ticks(b.burnSeconds(),d));
            case VowStrikeBehavior b -> new VowStrikeBehavior(b.damage(),b.perPoint(),b.knockback()*Math.sqrt(p)*t.details().force()/100.0);
            default -> behavior;
        };
    }
}
